// Illustrative: Request-Reply is an exchange between two parties over two channels, not a transformation of one stream, so this sketch does not run.
const reply$ = replies$.pipe(
  // The reply channel is replies$: receipts are skipped, and any result counts as the reply.
  filter(isResult),
  // The wait: the requestor takes one reply, then stops listening.
  first(),
  // The deadline: no reply in time is an error, and the error is the timeout path.
  timeout({ first: deadline }),
);

// Asynchronous callback: listen on the reply channel, send on the request channel, carry on.
reply$.subscribe({ next: resume, error: takeTimeoutPath });
requests$.next(command);

// Synchronous block, the other choice: listen, send, then stop until the reply or the deadline.
const pending = firstValueFrom(reply$);
requests$.next(command);
const result = await pending;
